// The deployed Worker entry is generated by Void from `packages/worker/app`
// (routes, crons, queues) plus `./entry-classes`. This module wires the same
// handlers for `wrangler types` and the workerd integration-test pool.
import { app } from "./app";
import { handleQueue } from "./queue-handler";
import { handleScheduled } from "./scheduled-handler";

// Named, so `wrangler types` can type the Durable Object and Workflow bindings.
export { OutboxDeliveryWorkflow, StreamHub } from "./entry-classes";

export default {
  fetch: (request, env, ctx) => app.fetch(request, env, ctx),
  queue: handleQueue,
  scheduled: handleScheduled,
} satisfies ExportedHandler<Env>;
